# Let me try a direct backtracking search with constraint propagation
import sys

n = 7

# We'll fill the grid cell by cell
# Use constraint propagation to prune the search space

def solve():
    # Initialize grid with -1 (unfilled)
    grid = [[-1]*n for _ in range(n)]

    # Domain for each cell
    domain = [[set(range(n)) for _ in range(n)] for _ in range(n)]

    # Set diagonal
    for i in range(n):
        grid[i][i] = i
        for j in range(n):
            if j != i:
                domain[i][j].discard(i)
                domain[j][i].discard(i)

    # Propagate Latin square constraints
    def propagate():
        changed = True
        while changed:
            changed = False
            # Row constraints
            for i in range(n):
                for j in range(n):
                    if grid[i][j] != -1:
                        val = grid[i][j]
                        for k in range(n):
                            if k != j and val in domain[i][k]:
                                domain[i][k].discard(val)
                                changed = True
            # Column constraints
            for j in range(n):
                for i in range(n):
                    if grid[i][j] != -1:
                        val = grid[i][j]
                        for k in range(n):
                            if k != i and val in domain[k][j]:
                                domain[k][j].discard(val)
                                changed = True
        return True

    propagate()

    # Check for empty domains
    for i in range(n):
        for j in range(n):
            if grid[i][j] == -1 and len(domain[i][j]) == 0:
                return None

    # Now do backtracking search
    # Order cells by most constrained first
    def get_next_cell():
        best = None
        best_size = n + 1
        for i in range(n):
            for j in range(n):
                if grid[i][j] == -1:
                    size = len(domain[i][j])
                    if size < best_size:
                        best_size = size
                        best = (i, j)
        return best

    def check_qg3_partial(i, j, val):
        # Check QG3 constraints that involve this cell
        # x[x[i][j]][x[j][i]] = i
        # If we set x[i][j] = val, we need to check:
        # 1. If x[j][i] is known (say b), then x[val][b] must be i
        # 2. For any k where x[k][i] = val and x[i][k] is known (say b), then x[val][b] = k
        # 3. For any k where x[i][k] = val and x[k][i] is known (say b), then x[val][b] = i

        # Actually, let's just check all QG3 constraints that can be checked now
        for a in range(n):
            for b in range(n):
                if grid[a][b] != -1 and grid[b][a] != -1:
                    ga = grid[a][b]
                    gb = grid[b][a]
                    if grid[ga][gb] != -1 and grid[ga][gb] != a:
                        return False
        return True

    def backtrack():
        cell = get_next_cell()
        if cell is None:
            # All cells filled, verify QG3
            for i in range(n):
                for j in range(n):
                    a = grid[i][j]
                    b = grid[j][i]
                    if grid[a][b] != i:
                        return False
            return True

        i, j = cell
        for val in sorted(domain[i][j]):
            # Save state
            old_grid = grid[i][j]
            old_domains = [row[:] for row in domain]

            grid[i][j] = val

            # Propagate
            # Remove val from row i and column j
            for k in range(n):
                if k != j and val in domain[i][k]:
                    domain[i][k].discard(val)
                if k != i and val in domain[k][j]:
                    domain[k][j].discard(val)

            # Check for empty domains
            valid = True
            for ii in range(n):
                for jj in range(n):
                    if grid[ii][jj] == -1 and len(domain[ii][jj]) == 0:
                        valid = False
                        break
                if not valid:
                    break

            if valid and check_qg3_partial(i, j, val):
                if backtrack():
                    return True

            # Restore
            grid[i][j] = old_grid
            for ii in range(n):
                for jj in range(n):
                    domain[ii][jj] = old_domains[ii][jj]

        return False

    if backtrack():
        return grid
    return None

result = solve()
if result:
    print("Solution found:")
    for row in result:
        print(row)
    flat = [result[i][j] for i in range(n) for j in range(n)]
    print(f"Flat: {flat}")
else:
    print("UNSATISFIABLE")

# Let me try a smarter approach - use the structure of QG3 quasigroups
# QG3 is a well-studied identity. Let me try to construct one systematically.

# For QG3: x[x[i][j]][x[j][i]] = i
# This is equivalent to saying that the map (i,j) -> (x[i][j], x[j][i]) is an involution
# when composed with x.

# Let me try a different encoding with pysat
from pysat.solvers import Glucose3

n = 7

# Variables: x[i][j] = k is represented by variable (i*n + j)*n + k + 1
def var(i, j, k):
    return (i * n + j) * n + k + 1

solver = Glucose3()

# Exactly one value per cell
for i in range(n):
    for j in range(n):
        # At least one value
        solver.add_clause([var(i, j, k) for k in range(n)])
        # At most one value
        for k1 in range(n):
            for k2 in range(k1+1, n):
                solver.add_clause([-var(i, j, k1), -var(i, j, k2)])

# Latin square: each row has distinct values
for i in range(n):
    for j1 in range(n):
        for j2 in range(j1+1, n):
            for k in range(n):
                solver.add_clause([-var(i, j1, k), -var(i, j2, k)])

# Latin square: each column has distinct values
for j in range(n):
    for i1 in range(n):
        for i2 in range(i1+1, n):
            for k in range(n):
                solver.add_clause([-var(i1, j, k), -var(i2, j, k)])

# Idempotent diagonal
for i in range(n):
    solver.add_clause([var(i, i, i)])

# QG3: x[x[i][j]][x[j][i]] = i
# For each i, j: if x[i][j] = a and x[j][i] = b, then x[a][b] = i
# This is: for all i, j, a, b: NOT(x[i][j]=a AND x[j][i]=b AND x[a][b]!=i)
# Equivalently: for all i, j, a, b: -var(i,j,a) OR -var(j,i,b) OR var(a,b,i)

for i in range(n):
    for j in range(n):
        for a in range(n):
            for b in range(n):
                solver.add_clause([-var(i, j, a), -var(j, i, b), var(a, b, i)])

print(f"Variables: {solver.nof_vars()}, Clauses: {solver.nof_clauses()}")
print("Solving...")

if solver.solve():
    model = solver.get_model()
    grid = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                if var(i, j, k) in model:
                    grid[i][j] = k
                    break

    print("Solution found:")
    for row in grid:
        print(row)

    # Verify
    for i in range(n):
        for j in range(n):
            a = grid[i][j]
            b = grid[j][i]
            assert grid[a][b] == i, f"QG3 failed at ({i},{j}): x[{a}][{b}] = {grid[a][b]} != {i}"
    print("Verified!")

    flat = [grid[i][j] for i in range(n) for j in range(n)]
    print(f"Flat: {flat}")
else:
    print("UNSATISFIABLE")

